import json, numpy as np
from scipy.optimize import minimize_scalar
D=json.load(open('data/calibration.json'))
C=1e6*np.array([[6,2,.8],[2,4,.6],[.8,.6,3.]])
K=1e-15*np.array([[1,.2],[.2,.6]])
a=.9; M=20e6; L=.01; g=1e-10
s0=1/M+a*a*np.array([1,1,0])@np.linalg.solve(C,np.array([1,1,0]))

def coeff(e, kind):
    m=np.array(e['mode'],float); k=2*np.pi/L*m
    cond=k@K@k+g
    if kind=='local': s=s0
    else:
      if np.all(k==0): s=s0
      else:
        B=np.array([[k[0],0],[0,k[1]],[k[1],k[0]]])
        A=B.T@C@B
        s=1/M+a*a*k@np.linalg.solve(A,k)
    return s,cond
for kind in ['local','spectral']:
 def loss(mu):
  rr=[]
  for r in D:
   s,c=coeff(r['input'],kind)
   e=r['input']; pred=e['initial_pressure']*np.exp(-c*e['time']/mu/s)
   rr.append((pred-r['value'])/r['sigma'])
  return np.mean(np.array(rr)**2)
 res=minimize_scalar(loss,bounds=(.0008,.0015),method='bounded',options={'xatol':1e-15})
